```python
def maxAverageOfPath(matrix):
    n = len(matrix)
    max_avg = 0
    for i in range(n):
        for j in range(n):
            if i == 0 and j == 0:
                continue
            current_sum = sum(matrix[i][j])
            current_count = i + j + 1
            if current_count > max_avg:
                max_avg = current_sum / current_count
    return max_avg
```

